local Text_AwakerTalent = readonly({
  AwakerTalent_117311_TalentDesc_1 = {
    Text = "・ポリュクスが毎ターン初めて使用する指令カードは、ダメージが自身の攻撃力の200％増加し、シールドが自身の防御の50%増加し、ポリュクスに10狂気を獲得させる。\n・戦闘終了後、この探索中にポリュクスが与える基礎ダメージと「苦痛による贖罪」のダメージ増加効果が20%増加する。ボス戦では「苦痛による贖罪」のダメージ増加効果が2倍になる。"
  },
  AwakerTalent_117311_TalentName_1 = {
    Text = "苦痛による贖罪"
  },
  AwakerTalent_120347_TalentDesc_1 = {
    Text = "·このキャラクターがパーティにいる場合、「深海」界域を「暗冥・深海」界域に置き換える。\n·基本触腕ダメージがパーティの最大ライフの5％に変更される。\n·探索開始後、パーティのダメージ強化+50％。パーティが深海または混沌覚醒体のみで構成されている場合、この効果で得られるダメージ強化が2倍になるが、戦闘開始時に追加の触腕を得なくなる。\n·「触手集合」効果を持たなくなる。\n·触腕モードが「暗冥・触腕モード」に変更される。\n·「暗冥・静海」：最大ライフの25％のシールドを獲得し、ターン終了後に触腕が攻撃しなくなる。クールダウン3ターン。\n·「暗冥・怒涛」：このターンの触腕ダメージを125％にし、アクティブダメージを与えた後に触腕1本が攻撃するが、ターン終了後に触腕を1本失う。クールダウン3ターン。\n·界域知識が「暗冥・深海の精通」に変更され、界域知識1点ごとに「暗冥・静海」のシールドが最大ライフの0.025％増加し、「暗冥・怒涛」の触腕ダメージが追加で0.025％増加する。\n·パーティが深海または混沌覚醒体のみで構成されている場合、「暗冥・界域知識」の効果が2倍になる。"
  },
  AwakerTalent_120347_TalentName_1 = {
    Text = "永暗の地"
  },
  AwakerTalent_122481_TalentDesc_1 = {
    Text = "・この天賦は「星辰篇」ステージでのみ有効。\n・該当の覚醒体の体力、攻撃力、防御が[Arg1]%増加し、この覚醒体が初めて霊知覚醒を使用した後、[Arg2]キーエネルギーを獲得する。\n・ムシェットが「支配者」の敵に与える最終ダメージが[Arg5]%増加する。\n・すべての覚醒体の「攻撃」の基礎ダメージが[Arg3]%増加する。\n・死亡抵抗が発動した後、ムシェットは[Arg4]狂気を獲得。"
  },
