  AwakerTalent_122607_TalentDesc_1 = {
    Text = "・「攻撃」を2枚使用するたび、ムシェットが追撃を行い、ランダムに1回、ムシェットの攻撃力30%のダメージを与える。このダメージは「攻撃」として扱う。毎ターン最大4回まで発動する。"
  },
  AwakerTalent_122607_TalentName_1 = {
    Text = "ドラマチックな出会い"
  },
  AwakerTalent_125362_TalentDesc_1 = {
    Text = "·この天賦は「星辰篇」ステージでのみ有効。\n·この覚醒体の体力・攻撃・防御が [Arg1] ％上昇し、この覚醒体が初めて霊知啓発を発射した後、[Arg2] 点のキーエネルギーを獲得する。\n·すべての覚醒体が毒効果を発動する際の効果が [Arg3]％ 上昇する。\n·「酔い痴れ」1層ごとに「人型」敵が与えるダメージをさらに 1％ 減少させ、解除時に「人型」敵にさらに最大ライフの 1％ の純粋ダメージを与える。"
  },
