  AwakerTalent_127223_TalentDesc_1 = {
    Text = "·アラクネがチームにいる時、「超次元」領域を「特異点・超次元」領域に置き換える。\n·次元シャトル：毎ターン最初に指令カードを発射した後にこの効果を発動し、一時的なオリジナルコピーを超次元空間に置き、そのカードと一時的なコピーに25スタックの「奇点ビーコン」を付与する。超次元ターン中はこの効果を発動できない。\n·奇点ビーコン：1スタックごとにそのカードが与えるダメージ、固定力と触腕ダメージ上昇、固定毒、固定カウンターの最終効果が2%上昇し、固定シールド、固定ライフ回復、力減少の最終効果が1%上昇する。発射後に除去される。奇点ビーコンを持つカードは「次元シャトル」を発動できない。\n·超次元空間：超次元空間が上限に達した時、ターン終了時の処理が超次元空間の発動に変わる：追加ターンを獲得せず、保留以外の手札を捨てて虚無効果を発動し、超次元空間の全カードを手札に加え、現在の行動力を5ポイントに設定する。超次元空間を発動した後、そのターンは超次元ターンとみなす。\n·「特異点・湮滅」：超次元空間の最も左側のカードを取り出す。3ターンクールダウン。\n·探索開始後、チームのダメージ強化+50%、および15スタックの「特異点プリズム」を獲得する。\n·「特異点プリズム」：全指令カードが同等スタック数の奇点ビーコンのボーナスを持つとみなす。\n·超次元の知識：チームの界域知識が1ポイントあるごとに、「特異点プリズム」と「次元シャトル」が付与する「奇点ビーコン」のスタック数が0.05％上昇する。\n·超次元のみ：チームが超次元または混沌覚醒体のみで構成されている場合、超次元の知識の効果と領域が提供するダメージ強化が2倍になる。"
  },
  AwakerTalent_127223_TalentName_1 = {
    Text = "運命の糸"
  },
