  AwakerTalent_130398_TalentDesc_1 = {
    Text = "·この天賦は「星辰篇」のステージでのみ有効。\n·この覚醒体の体力、攻撃、防御が [Arg1] ％ 上昇し、この覚醒体が初めて霊知啓発を発射した後に [Arg2] 点のキーエネルギーを獲得する。\n·「サヤの歌」で選択した覚醒体が [Arg3] 層の「繁殖祭典」を獲得し、次のキーオーダーを 2 回発動させる。\n·サヤが「血肉」の敵に与える「侵蝕」が追加で [Arg4]％ 上昇する。"
  },
