  AwakerTalent_130400_TalentDesc_1 = {
    Text = "·この天賦は「星辰篇」関卡でのみ有効です。\n·この覚醒体の体力・攻撃・防御が [Arg1] ％上昇し、この覚醒体が初めて霊知啓発を発射した後、[Arg2] 点のキーエネルギーを獲得します。\n·「無辺荒影」が与える力減少効果・獲得する力倍率が [Arg3]％上昇し、効果が発動するたびに次の「染罪枪锋」が追加で [Arg4]％の力ボーナスを受け、上限は1200％です。"
  },
