  AwakerTalent_130919_TalentDesc_1 = {
    Text = "·このキャラクターがパーティにいる場合、「深海」界域を「暗冥・深海」界域に置き換える。\n·基本触腕ダメージがパーティの最大ライフの5％に変更される。\n·探索開始後、パーティのダメージ強化+50％。パーティが深海または混沌覚醒体のみで構成されている場合、この効果で得られるダメージ強化が2倍になるが、戦闘開始時に追加の触腕を得なくなる。\n·「触手集合」効果を持たなくなる。\n·触腕モードが「暗冥・触腕モード」に変更される。\n·「暗冥・静海」：最大ライフの25％のシールドを獲得し、ターン終了後に触腕が攻撃しなくなる。クールダウン3ターン。\n·「暗冥・怒涛」：このターンの触腕ダメージを125％にし、アクティブダメージを与えた後に触腕1本が攻撃するが、ターン終了後に触腕を1本失う。クールダウン3ターン。\n·界域知識が「暗冥・深海の精通」に変更され、界域知識1点ごとに「暗冥・静海」のシールドが最大ライフの0.025％増加し、「暗冥・怒涛」の触腕ダメージが追加で0.025％増加する。\n·パーティが深海または混沌覚醒体のみで構成されている場合、「暗冥・界域知識」の効果が2倍になる。"
  },
  AwakerTalent_130919_TalentName_1 = {
    Text = "永暗の地"
  },
  AwakerTalent_130920_TalentDesc_1 = {
    Text = "·この天賦は「星辰篇」ステージでのみ有効。\n·この覚醒体の体力・攻撃・防御が [Arg1] ％上昇し、この覚醒体が初めて霊知啓発を発射した後、[Arg2] 点のキーエネルギーを獲得する。\n·「渦！流！弾！」の固定ダメージが [Arg3]％ 上昇する。\n·モスが狂気解放を発動する前に、対象の「堅固」と「一時的な堅固」効果を解除し、解除に成功した場合、今回の狂気解放のクリティカルダメージ + [Arg4]％。"
  },
