  },
  AwakerTalent_131854_TalentDesc_1 = {
    Text = "·沙耶が編成にいる時、「血肉」界域を「繁殖・血肉」界域に置き換える。\n·胚胎融合：毎ターン獲得する胚胎融合が50〜100に上昇し、損失ライフに応じて上昇するが、胚融合上限が100から200に引き上げられ、上限に達した時「繁殖胚胎」を手札に加える。\n·繁殖胚胎：発射時にクリティカル率を獲得しなくなり、捕食もシールドと一時的な力を獲得しなくなる。各覚醒体が毎ターン初めて「繁殖胚胎」を消費した時、40層の「繁殖祭典」を獲得する：1層ごとにその覚醒体の今ターン次の狂気解放が与えるダメージ・固定シールド・固定ライフ回復・固定力・力減少・触腕ダメージ上昇・固定毒・固定反撃の最終効果が1％上昇する。\n·猩紅炉：ターン開始時の自動蓄積量が損失ライフの10%に変更され、最大蓄積量が最大ライフの50%に変更される。戦闘終了時は蓄積されなくなり、使用時に3ターンのクールダウンが発生する。\n·深紅の侵蝕：猩紅炉使用後、全敵に対象の最大ライフ1%の侵蝕を与え、消費した猩紅炉が多いほど侵蝕効果が強くなり、最大100%上昇する。「空殻」の敵に対しては5倍の侵蝕効果を与える。\n·探索開始後、最大ライフが10％上昇し、編成のダメージ強化+50%、毎ターン開始時に全覚醒体が20層の「繁殖祭典」を獲得する。編成が血肉または混沌覚醒体のみで構成されている場合、この効果で得られるダメージ強化が2倍になる。\n·界域知識は「繁殖・血肉精通」に変わり、界域知識1ポイントごとに「繁殖・血肉」で獲得する「繁殖祭典」が0.05%上昇する。\n·編成が血肉または混沌覚醒体のみで構成されている場合、「繁殖・血肉精通」の効果が2倍になる。"
  },
  AwakerTalent_131854_TalentName_1 = {
    Text = "繁殖の浄土"
  },
