    Text = "・この天賦は「星辰篇」のステージでのみ有効。\n・該当の覚醒体の体力、攻撃、防御が[Arg1]%増加し、その覚醒体が初めて霊知啓発を発射した後[Arg2]キーエネルギーを獲得。\n・「ポントス」が「歓喜の同族」に与える固定ダメージが[Arg3]％増加する。\n・「終わりなき狩宴」は狂気を10消費するごとに[Arg4]％の攻撃力の触腕ダメージを獲得し、「魘鬼急襲」はダメージを与えた際に一時的にターゲットの防御の[Arg5]％分の力を低下させる。"
  },
