  AwakerTalent_145381_TalentDesc_1 = {
    Text = "·この天賦は「星辰篇」ステージでのみ有効。\n·この覚醒体の体力・攻撃・防御が[Arg1]%上昇し、この覚醒体が初めて霊知啓発を発射した後に[Arg2]ポイントのキーエネルギーを獲得する。\n·「断界の剣」は追加で[Arg3]％の力ボーナスを受け、敵をキルした後に[Arg4]ブラックスタンプを獲得し、自身の黒章ドロップ率ボーナスを受ける。1戦闘につき最大1回有効。"
  },
