  AwakerTalent_145718_TalentDesc_1 = {
    Text = "·カラブが編成にいる時、「血肉」界域を「繁殖・血肉」界域に置き換える。\n·胚胎融合：毎ターン獲得する胚胎融合が50〜100に上昇し、損失ライフに応じて上昇するが、胚融合上限が100から200に引き上げられ、上限に達した時「繁殖胚胎」を手札に加える。\n·繁殖胚胎：発射時にクリティカル率を獲得しなくなり、捕食もシールドと一時的な力を獲得しなくなる。各覚醒体が毎ターン初めて「繁殖胚胎」を消費した時、40層の「繁殖祭典」を獲得する：1層ごとにその覚醒体の今ターン次の狂気解放が与えるダメージ・固定シールド・固定ライフ回復・固定力・力減少・触腕ダメージ上昇・固定毒・固定反撃の最終効果が1％上昇する。\n·猩紅炉：ターン開始時の自動蓄積量が損失ライフの10%に変更され、最大蓄積量が最大ライフの50%に変更される。戦闘終了時は蓄積されなくなり、使用時に3ターンのクールダウンが発生する。\n·深紅の侵蝕：猩紅炉使用後、全敵に対象の最大ライフ1%の侵蝕を与え、消費した猩紅炉が多いほど侵蝕効果が強くなり、最大100%上昇する。「空殻」の敵に対しては5倍の侵蝕効果を与える。\n·探索開始後、最大ライフが10％上昇し、編成のダメージ強化+50%、毎ターン開始時に全覚醒体が20層の「繁殖祭典」を獲得する。編成が血肉または混沌覚醒体のみで構成されている場合、この効果で得られるダメージ強化が2倍になる。\n·界域知識は「繁殖・血肉精通」に変わり、界域知識1ポイントごとに「繁殖・血肉」で獲得する「繁殖祭典」が0.05%上昇する。\n·編成が血肉または混沌覚醒体のみで構成されている場合、「繁殖・血肉精通」の効果が2倍になる。"
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "繁殖の浄土"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "·蝕滅・ロータンがチームにいる時、「混沌」領域を「原初・混沌」領域に置き換える。\n·原初の注入：基礎キーエネルギーが2000ポイントに上昇し、チームのダメージ強化+50%、全覚醒体の攻撃と防御が10%上昇する。チームが混沌覚醒体のみで構成されている場合、この効果で得られるダメージ強化が2倍になる。戦闘開始時、2000ポイントのキーエネルギーを獲得する。\n·同源の鍵：全覚醒体のシルバーキー充電レベルがチームの平均値になる。また、行動力消費によるキーエネルギー獲得がなくなり、代わりに各覚醒体が毎ターン最初の指令カードで「その覚醒体のシルバーキー充電×3+100」のキーエネルギーを獲得する。\n·不可分の領域：他の領域の超次元のみ、知識効果2倍、強力2倍効果を発動しなくなる。\n·原初の反響：霊知啓発が準備1を獲得し、毎ターン最初に発射した時に自動的に保有キーオーダーを発動する。\n·記憶の欠片：キーオーダーが「原初・双生の再演」と「原初・三相の啓示」に置き換えられ、本来保有しているキーオーダーは発動できなくなる。\n·原初・双生の再演：保有キーオーダーから3種のキーオーダーを発見し、1つのキーオーダーを選択して2回発動させる。\n·原初・三相の啓示：保有キーオーダーから3組のキーオーダーを発見し、各組は3種の異なるキーオーダーで構成される。1組を選択してその中のキーオーダーを順番に1回ずつ発動させる。\n·原初・双生の再演と原初・三相の啓示に含まれるキーオーダーには八種の「原初の記憶」が含まれる。\n·原初・双生の再演と原初・三相の啓示はキーオーダーを1回発動したとみなし、複数回発動する場合は最初に発動したキーオーダーにのみ有効となる。\n·界域知識が「原初・混沌精通」に変わり、1ポイントの界域知識ごとにキーオーダーの強度が0.05%上昇する。\n·1ポイントのキーオーダー強度ごとに、キーオーダーが与える固定毒、固定カウンター、固定力、固定触腕ダメージ、固定古代の灰を2%上昇させ、固定シールド、固定ライフ回復、力減少、クリティカル率、クリティカルダメージ、ダメージ強化、界域知識、狂気、胎児融合、キーエネルギーを1%上昇させる。\n·チームが混沌覚醒体のみで構成されている場合、「原初・混沌精通」の効果が2倍になる。"
  },
  AwakerTalent_146937_TalentName_1 = {
    Text = "混沌の息吹"
  },
