    Text = "・リリー自身、装備中の命輪と密契が死亡抵抗の能力を1%獲得するごとに、「黒沼禁域」と「防御」の基礎シールドが0.25%増加し、ボス戦における「忍耐」の蓄積量と上限が0.25%増加する。\n・リリーがチームにいる場合、ライフを1失うごとに1点の「忍耐」を獲得する。「忍耐」の上限は最大ライフに等しい。"
