  AwakerTalent_46445_TalentDesc_1 = {
    Text = "・サルバドルがの猩紅炉蓄積量は、ライフ回復ボーナスを獲得する。"
  },
  AwakerTalent_46445_TalentName_1 = {
    Text = "霊魂の牧人"
  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = "・ラモンナは追加で2.5点のキーチャージを獲得する。同調率のレベルに応じて、ラモンナは追加で0.5点のキーチャージを獲得する。\n・キーチャージを1点獲得するごとに、「女王の剣」の基礎ダメージが1%増加し、使用後、0.75点の一時的な界域知識を獲得する。"
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "心と銀の共鳴"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = "・環行・ラモンナは追加で2.5点のキーチャージ能力を獲得する。同調率のレベルに応じて、環行・ラモンナは追加で0.5点のキーチャージ能力を獲得する。\n・キーチャージ能力を1点獲得するごとに、「攻撃」のループ効果は0.2%のクリティカル率を獲得し、「防御」のループ効果は0.2狂気を獲得する。"
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "心と銀の共鳴"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "・ナウティラが界域知識の能力を1点獲得するごとに、「準備完了」で獲得する反撃が0.25%増加する。"
  },
  AwakerTalent_49872_TalentName_1 = {Text = "点検"},
  AwakerTalent_49873_TalentDesc_1 = {
    Text = "・ニムフィーアがダメージ強化の能力を1%各遠くするごとに、「弔いの鐘の音」と「自我の葬儀」付与する毒が0.5%増加する。"
  },
  AwakerTalent_51744_TalentDesc_1 = {
    Text = "・戦闘開始時、「執妄」を1枚手札に追加する。\n・ミリアムの「基礎打撃」は100%の触腕ダメージボーナスを獲得する。\n・ミリアム覚醒体自身、命輪、密契がクリティカルダメージの能力を1%提供するごとに、狂気解放で獲得する力、触腕ダメージ、狂気、付与する毒と毒発動効果が0.2%増加する。"
  },
  AwakerTalent_51744_TalentName_1 = {
    Text = "不滅の信仰"
  },
  AwakerTalent_52071_TalentDesc_1 = {
    Text = "・トゥルー自身、装備中の命輪および密契が狂気増加の能力を1点獲得するごとに、「攻撃」は5%の触腕ダメージと力ボーナスを獲得し、「深淵の号令」は15%の触腕ダメージと力ボーナスを獲得する。"
  },
  AwakerTalent_52071_TalentName_1 = {
    Text = "神王の権能"
  },
  AwakerTalent_52086_TalentDesc_1 = {
    Text = "・サンガー自身、装備する命輪と密契が死亡抵抗の能力を1%獲得するごとに、「攻撃」と「防御」で獲得する狂気が0.03増加し、「失われた芸術」は追加で0.15%のクリティカル率とクリティカルダメージボーナスを獲得する。"
  },
  AwakerTalent_52086_TalentName_1 = {
    Text = "死の啓示"
  },
  AwakerTalent_54047_TalentDesc_1 = {
    Text = "・ドールが狂気増加の能力を1点持つごとに、「外界手術」と「等価交換」のライフ回復効果が0.5%増加する。"
  },
  AwakerTalent_54047_TalentName_1 = {
    Text = "霊知の解体"
  },
  AwakerTalent_54072_TalentDesc_1 = {
    Text = "・オジールが黒章ドロップ率の能力を1%獲得するごとに、「七つの技、継承した美徳」で獲得する一時的な力が3%増加する。"
  },
  AwakerTalent_54072_TalentName_1 = {
