  AwakerTalent_54158_TalentDesc_1 = {
    Text = "・ソレール自身、装備中の命輪と密契がクリティカル率の能力を1%獲得するごとに、「防御」で獲得する狂気が0.2増加する。"
  },
  AwakerTalent_54158_TalentName_1 = {
    Text = "虚飾を守る者"
  },
  AwakerTalent_55109_TalentDesc_1 = {
    Text = "・ジャンキン自身、装備中の命輪と密契がクリティカル率の能力を1%獲得するごとに、「攻撃」と「ブラウン出撃！」の基礎ダメージが2%増加する。"
  },
  AwakerTalent_55109_TalentName_1 = {
    Text = "共通の敵"
  },
  AwakerTalent_55176_TalentDesc_1 = {
    Text = "・エリカ覚醒体自身、命輪、密契がキーチャージの能力を1点提供するごとに、「電磁爆破」でエリカが獲得する一時的なクリティカル率とクリティカルダメージが0.5%増加する。"
  },
  AwakerTalent_55176_TalentName_1 = {
    Text = "外部電源"
  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = "・ターン開始時、1点の夢引きを獲得する。\n・夢引きを1点消費するごとに、この戦闘中に「迷い人の守護」と「死せる夢の都」が獲得する反撃が攻撃力の5%増加する。\n・ワンダ自身、装備中の命輪と密契がダメージ強化の能力を1%獲得するごとに、「死せる夢の都」が獲得する反撃が0.75%増加する。"
  },
  AwakerTalent_55202_TalentName_1 = {Text = "啓示"},
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "・カーシア自身、装備中の命輪と密契が界域知識の能力を1点獲得するごとに、「マジックカーニバル」の基礎ダメージ増加効果が0.2%増加する。"
  },
  AwakerTalent_55367_TalentName_1 = {
    Text = "手品の達人"
  },
  AwakerTalent_55507_TalentDesc_1 = {
    Text = "・ティンクト自身、装備中の命輪と密契が黒章ドロップ率の能力を1%獲得するごとに、「「星の極光」で獲得する一時的なクリティカル率が0.15%増加する。"
  },
  AwakerTalent_55507_TalentName_1 = {
    Text = "惑星旅人"
  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "・オルラの「攻撃」と「防御」は詩篇として扱う。「交換所」での売却価格は30黒章。詩篇が「跳躍」効果を発動すると対応する「情緒」に切り替える。「情緒」ごとに、チームに付与する効果が異なる。オルラが死亡抵抗の能力を1%獲得するごとに、情緒効果ボーナスが0.1%増加する。"
  },
