  AwakerTalent_58448_TalentDesc_1 = {
    Text = "・ライカーが敵を撃破すると5黒章を獲得し、ライカーが黒章ドロップ率の能力を1%獲得するごとに、獲得量が1%増加する。この探索中、最大5回まで。\n・戦闘で50/125/250の黒章を獲得すると、遺物の上限+1、戦闘終了後に<C05_zaowu:「混沌の遺贈」>を遺物リストに追加する。"
