  AwakerTalent_70306_TalentDesc_1 = {
    Text = "·ボスバトル中、ターン開始時及び「メルトダウン・ドル」が狂気解放を発動した後、1層の「終末」を獲得する。「終末」は最大で10層まで保持でき、10層に達した時に1枚の「虚無終結」を手札に加える。"
  },
  AwakerTalent_70306_TalentName_1 = {
