  AwakerTalent_74118_TalentDesc_1 = {
    Text = "・この才能は「星辰篇」のステージでのみ有効。\n・該当の覚醒体の体力、攻撃、防御が[Arg1]%増加し、その覚醒体が初めて霊知啓発を使用した時[Arg2]キーエネルギーを獲得。\n・ゴリアが与える基礎ダメージが[Arg3]％増加、「巨刃の威」によりゴリアが与える最終ダメージが一時的に[Arg4]％増加。\n・チームに他の「リモリア」覚醒体が1/2/3名存在する場合、全覚醒体の力獲得効果がさらに6%/15%/30%増加。"
  },
