  AwakerTalent_78618_TalentDesc_1 = {
    Text = "・この才能は「星辰篇」のステージでのみ有効。\n・該当の覚醒体の体力、攻撃、防御が[Arg1]%増加し、その覚醒体が初めて霊知啓発を使用した時[Arg2]銀鍵エネルギーを獲得。\n・「苦痛救済」が付与する基礎ダメージ効果がポリュクスの攻撃力の[Arg3]％分増加する。\n・「罪印」が50層蓄積するごとに「聖心」1枚を手札に加える。\n・「罪印」が100層に達した後、「聖心」は3回目の使用で消費された際に自身の「スキルカード」を1枚ドローする。\n・ダメージを与える時、「罪印」の「提灯教会」の敵に対する効果が倍になる。"
