  AwakerTalent_78622_TalentDesc_1 = {
    Text = "・この才能は「星辰篇」のステージでのみ有効。\n・該当の覚醒体の体力、攻撃、防御が[Arg1]%増加し、その覚醒体が初めて霊知覚醒を発動した時[Arg2]点のシルバーキーエネルギーを獲得。\n・「活焔」の増益効果が[Arg3]％上昇し、ラウンド開始後と捨て札フェーズ前に、すべての手札の「燃焼」を除去し、1層ごとにケティグラが1層の「爆炎」を獲得する。"
