  AwakerTalent_78623_TalentDesc_1 = {
    Text = "·この天賦は「星辰篇」関卡でのみ有効です。\n·この覚醒体の体力・攻撃・防御が [Arg1] ％上昇し、この覚醒体が初めて霊知啓発を発射した後、[Arg2] 点のキーエネルギーを獲得します。\n·カラブの狂気解放のクリティカル率とクリティカルダメージが [Arg3]％上昇します。「飽満」が提供するライフ上限が [Arg5]％上昇します。「氷原」地形では、「粉雪の呪い」の行動力消費-1、ダメージ回数+1となり、ダメージと虚弱効果がすべての敵に有効になります。"
