  AwakerTalent_78624_TalentDesc_1 = {
    Text = "・この才能は「星辰篇」のステージでのみ有効。\n・該当の覚醒体の体力、攻撃、防御が[Arg1]%増加し、その覚醒体が初めて霊知啓発を使用した時[Arg2]キーエネルギーを獲得。\n・「黒羽」を使用しても「演算調和」が追加されず、「聖羽洗罪」が付与する侵蝕がカストルの攻撃力の[Arg3]％分増加。\n・カストルが「提灯教会」の敵に付与する侵蝕が[Arg4]％増加。"
