  AwakerTalent_78645_TalentDesc_1 = {
    Text = "・この才能は「星辰篇」のステージでのみ有効。\n・該当の覚醒体の体力、攻撃、防御が[Arg1]%増加し、その覚醒体が初めて霊知啓発を使用した時[Arg2]銀鍵エネルギーを獲得。\n・全ての覚醒体が獲得する力量が[Arg3]％増加。\n・クレメンティンが「蟲族」の敵にダメージを与えた時、対象に[Arg4]％ダメージの出血効果を付与。クレメンティンが毎ラウンド初めてシールドまたはHP回復を発生させた時、「蟲族」の敵の防御力[Arg5]％分の力量を一時的に失わせる。"
  },
