    Text = "・この才能は「星辰篇」のステージでのみ有効。\n・該当の覚醒体の体力、攻撃、防御が[Arg1]%増加し、その覚醒体が初めて霊知啓発を使用した時[Arg2]銀キーエネルギーを獲得。\n・誕妄·マーフィーが与えるダメージに[Arg3]％「献祭」を付与し、「命契」の「降生儀式」への増加効果が2倍になる。\n・チームに他の「リモリア」覚醒体が1/2/3名存在する時、HP上限が6%/15%/30％増加。「リモリア」覚醒体が狂気爆発を発動後、誕妄·マーフィーの防御力の50%/125%/250%のシールドを獲得する。この効果は毎ターン最大1回発動し、シールド増加効果の影響を受けない。"
  },
