  AwakerTalent_79211_TalentDesc_1 = {
    Text = "・クレメンタインの指令カードがダメージを与えた後、「共感」を1層獲得する。\n・クレメンタイン覚醒体自身、命輪、密契がキーチャージの能力を1点提供するごとに、クリティカル率とクリティカルダメージが0.35%増加する。\n・超次元ターン開始後、すべての敵の「精神創傷」と「恐怖固着」を除去する。すべての敵から「精神創傷」を1層除去するごとに50キーエネルギーを獲得し、すべての敵から「恐怖固着」を1層除去するごとに他の覚醒体が2狂気を獲得する。"
  },
